<?php
namespace FurMedia\Cache;
/** Conditional policies only narrow native admission. No POST/transaction caching. */
class Conditions {
 public static function parse($text){if(trim($text)===''){return array();}$rows=json_decode($text,true);if(!is_array($rows)||count($rows)>100){throw new \InvalidArgumentException('Conditions require at most 100 JSON rules');}foreach($rows as $row){if(!is_array($row)||!isset($row['route'])||!is_string($row['route'])||!preg_match('~^[a-z0-9_/]+$~D',$row['route'])){throw new \InvalidArgumentException('Invalid condition route');}foreach($row as $k=>$v){if(!in_array($k,array('route','get','config','session','ttl','enabled'),true)){throw new \InvalidArgumentException('Unknown condition option');}}foreach(array('get','config','session') as $kind){if(!isset($row[$kind])){continue;}if(!is_array($row[$kind])||count($row[$kind])>20){throw new \InvalidArgumentException('Invalid condition predicates');}foreach($row[$kind] as $key=>$value){$allowed=$kind==='get'?array('product_id','path','manufacturer_id','information_id','page','limit','sort','order','search','tag') : ($kind==='config'?array('config_store_id','config_language_id','config_customer_group_id','config_currency','config_theme'):array('language','currency'));if(!in_array($key,$allowed,true)||!is_scalar($value)||strlen((string)$value)>128){throw new \InvalidArgumentException('Unsupported or sensitive condition predicate');}}}if(isset($row['ttl'])&&(!is_numeric($row['ttl'])||$row['ttl']<10||$row['ttl']>86400)){throw new \InvalidArgumentException('Invalid condition TTL');}if(isset($row['enabled'])&&!in_array($row['enabled'],array(true,false,0,1),true)){throw new \InvalidArgumentException('Invalid condition flag');}}return $rows;}
 public static function match($text,$route,array $get,array $config,array $session){foreach(self::parse($text) as $row){if($row['route']!==$route){continue;}$matches=true;foreach(array('get'=>$get,'config'=>$config,'session'=>$session) as $kind=>$values){foreach(isset($row[$kind])?$row[$kind]:array() as $key=>$value){if(!isset($values[$key])||!is_scalar($values[$key])||(string)$values[$key] !== (string)$value){$matches=false;}}}if($matches){return $row;}}return null;}
}
